const {app,BrowserWindow}=require('electron'),fs=require('node:fs'),path=require('node:path'),os=require('node:os');
const {resolveMarkdownFile}=require('../../desktop/services/preview.cjs'),{markdownPages,markdownPageDocument}=require('../../desktop/services/markdown-pages.cjs');
app.disableHardwareAcceleration();const temp=fs.mkdtempSync(path.join(os.tmpdir(),'stable-md-preview-'));app.setPath('userData',temp);
(async()=>{await app.whenReady();const original='D:/stable-test/库迪8月逐店作业清单-王晓丹.md';const pages=markdownPages(resolveMarkdownFile(original,'D:/stable-test').content);const win=new BrowserWindow({show:false,width:1280,height:900,webPreferences:{javascript:false,sandbox:true,contextIsolation:true,nodeIntegration:false,backgroundThrottling:false}});let index=0;
const display=async n=>{index=n;const p=path.join(temp,'page-'+n+'.html');fs.writeFileSync(p,markdownPageDocument(pages,n,'完整作业清单','light'));await win.loadFile(p)};
win.webContents.on('will-navigate',(e,url)=>{e.preventDefault();const match=/^stable-markdown-page:(\d+)$/.exec(url);if(match)void display(Number(match[1]))});await display(0);
win.webContents.focus();win.webContents.sendInputEvent({type:'keyDown',keyCode:'Tab'});win.webContents.sendInputEvent({type:'keyUp',keyCode:'Tab'});win.webContents.sendInputEvent({type:'keyDown',keyCode:'Return'});win.webContents.sendInputEvent({type:'keyUp',keyCode:'Return'});for(let i=0;i<100&&index!==1;i++)await new Promise(r=>setTimeout(r,30));if(index!==1)throw Error('Page navigation failed');await new Promise(r=>setTimeout(r,300));
const out=path.resolve(__dirname,'../../../qa-artifacts/template-library-20260911/markdown-page.png');fs.writeFileSync(out,(await win.webContents.capturePage()).toPNG());console.log('MARKDOWN_UI_PASS pages='+pages.length+' current='+index);win.destroy();app.exit(0)})().catch(e=>{console.error(e.stack);app.exit(1)});
